installer-gui-script.script:
function csecInstallationCheck() {
    if (system.sysctl('hw.optional.arm64') != 1) {
        my.result.type = 'Fatal';
        my.result.title = 'Convenient Security needs a Mac with Apple silicon';
        my.result.message = 'This Mac has an Intel processor. Convenient Security runs only on Macs with Apple silicon (M1 or later), so nothing has been installed.';
        return false;
    }
    if (system.compareVersions(system.version.ProductVersion, '@MINIMUM_MACOS@') < 0) {
        my.result.type = 'Fatal';
        my.result.title = 'Convenient Security needs macOS @MINIMUM_MACOS@ or later';
        my.result.message = 'Update macOS in System Settings, then open this installer again. Nothing has been installed.';
        return false;
    }
    return true;
}
